() => {
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Debug Org (Claude)'));
  const panel = btn.parentElement.querySelector('div[class*="absolute"]');
  const out = { expanded: btn.getAttribute('aria-expanded'), panelFound: !!panel };
  if (panel) {
    const r = panel.getBoundingClientRect();
    out.panelRect = { top: r.top, left: r.left, w: r.width, h: r.height };
    out.panelVisible = getComputedStyle(panel).visibility;
  }
  // walk ancestors looking for clipping
  let el = btn.parentElement, chain = [];
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    chain.push({ tag: el.tagName, cls: el.className?.toString?.().slice(0,90), overflow: cs.overflow, height: cs.height, position: cs.position });
    el = el.parentElement;
  }
  out.chain = chain.slice(0, 6);
  return out;
}

