import { analytics } from "@repo/analytics/server";
import { auth } from "@repo/auth/server";
import { flag } from "flags/next";

export const createFlag = (key: string, description?: string) =>
  flag({
    key,
    description,
    defaultValue: false,
    options: [
      { value: true, label: "On" },
      { value: false, label: "Off" },
    ],
    async decide() {
      const { userId } = await auth();

      if (!userId) {
        return this.defaultValue as boolean;
      }

      // `flagKeys` keeps the /flags request scoped to the one flag we're
      // deciding; isFeatureEnabled is deprecated in posthog-node 5.x.
      const flags = await analytics.evaluateFlags(userId, { flagKeys: [key] });

      return flags.isEnabled(key) ?? (this.defaultValue as boolean);
    },
  });

